const skills = ($json.body?.skills || '').toLowerCase();
const category = /n8n|zapier|make|langchain|openai|automation/.test(skills) ? 'automation-heavy' : /fastapi|django|react|javascript/.test(skills) ? 'web-development' : /python|sql|pandas|data/.test(skills) ? 'data' : 'general';
return [{ json: { person_id: $json.body?.person_id, classification: category, classification_status: 'completed' } }];
